INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (155, "獣人族", "トゥインクルウィッシュ", 27, 8, "人助け、応援", 100101, "人助けが大好き！　前向き格闘娘", "ヒヨリ", 0, "東山奈央", 2, 44, 16, "A", "こんにちは！　ヒヨリでっす！\n困っている人がいたら助けにいくよ！\nよかったら一緒に来ない？");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (158, "ヒューマン", "トゥインクルウィッシュ", 5, 4, "料理、人間観察", 100201, "戦闘のサポートが得意な、心優しい少女", "ユイ", 0, "種田梨沙", 2, 47, 17, "O", "あんまり役に立てるかはわからないけど…\nわたしも頑張って、\nみんなをサポートするね！");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (163, "魔族", "トゥインクルウィッシュ", 12, 1, "読書、乗馬、お茶", 100301, "クールで何事にも真っ直ぐな剣士", "レイ", 0, "早見沙織", 2, 46, 18, "B", "キミと会ったのもきっと何かの縁だ\n一緒に塔の頂上を目指す仲間として\n頑張っていこう。よろしく頼む");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (128, "ヒューマン", "リトルリリカル", 10, 8, "いたずら、探検", 100401, "探検好きのイタズラっ子", "ミソギ", 0, "諸星すみれ", 5, 27, 9, "O", "イタズラなら任せて！\nにいちゃん、引っかからないように気を付けなよー♪");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (146, "獣人族", "王宮騎士団（NIGHTMARE）", 25, 11, "ヒーローごっこ", 100501, "ヒーローに憧れる騎士見習いの少女", "マツリ", 0, "下田麻美", 8, 40, 12, "O", "？？？");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (150, "魔族", "悪魔偽王国軍（ディアボロス）", 22, 11, "サックス", 100601, "甘え上手なみんなの人気者", "アカリ", 0, "浅倉杏美", 7, 42, 13, "O", "アカリ、まだわからないことが多くて…\nだからこれから\nいろいろ教えてくださいね、お兄ちゃん！");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (130, "魔族", "悪魔偽王国軍（ディアボロス）", 23, 1, "プリンを食べること", 100701, "プリン大好きゴースト娘", "ミヤコ", 0, "雨宮天", 7, 32, 14, "B", "難しいことはわからないの～\nただ毎日プリンを食べられるなら、\n幽霊のままでいいの～");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (150, "エルフ", "ヴァイスフリューゲル　ランドソル支部", 10, 10, "鏡で自分を見ること", 100801, "ボクは誰よりも美しい", "ユキ", 0, "大空直美", 15, 40, 14, "AB", "ボクって本当に美しいなあ…\n可愛くて美しいなんて本当に罪だと思うけど\n生まれもったものだから仕方ないんだ♪");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (159, "魔族", "トワイライトキャラバン", 5, 7, "小説執筆", 100901, "前世を信じる中二病患者、「疾風の冥姫」", "アンナ", 0, "髙野麻美", 13, 45, 17, "A", "いいか、絶対に私を真名で呼ぶなよ？\n常に「機関」の眼や耳の存在を疑え\nそれが、生きのびるための術だ…！");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (155, "獣人族", "自警団（カォン）", 22, 9, "空想、ぬいぐるみ集め", 101001, "マホマホ王国のプリンセス", "マホ", 0, "内田真礼", 10, 42, 16, "O", "マホマホ王国のお姫はんの、マホ姫どす！\nけったいな顔してどないしはったん？\nマホマホ王国はずーっと遠くの国なんどす？");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (156, "ヒューマン", "ラビリンス", 25, 8, "お裁縫", 101101, "人懐っこくてマシンガントークな妹系少女", "リノ", 0, "阿澄佳奈", 3, 44, 15, "A", "覚えていないと思うんですけど…\n私は妹なんですよ！\nだからお兄ちゃんって呼んでいいですか？");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (156, "エルフ", "フォレスティエ", 24, 12, "妹と遊ぶこと、二度寝、昼寝、早寝", 101201, "みんなのために超能力を使う眠り姫", "ハツネ", 0, "大橋彩香", 6, 46, 17, "A", "私はハツネ！　困っている人の味方だよ！\n困った時は、いつでも言ってね♪\n私のちょ…ま、魔法で助けてあげるから！");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (166, "魔族", "トワイライトキャラバン", 21, 8, "読書、魔法", 101301, "オタク全開な魔法少女", "ナナカ", 0, "佳村はるか", 13, 55, 18, "O", "");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (152, "獣人族", "自警団（カォン）", 3, 11, "読書、推理", 101401, "頭脳明晰な美少女名探偵", "カスミ", 0, "水瀬いのり", 10, 41, 15, "AB", "test");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (165, "エルフ", "フォレスティエ", 5, 9, "絵本作り", 101501, "母性溢れる優しいみんなの「ミサト先生」", "ミサト", 0, "國府田マリ子", 6, 54, 21, "O", "test");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (167, "魔族", "ルーセント学院", 10, 4, "ファッション", 101601, "天真爛漫で人気者のカリスマモデル", "スズナ", 0, "上坂すみれ", 14, 48, 17, "O", "ヒデサイ、ちょっす～！　うち、漢字と計算は\nちょっち…てか、おに苦手なんだ～\nでもでも、ファッションだったら任せて～！");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (158, "獣人族", "自警団（カォン）", 7, 7, "踊り、空手", 101701, "いつでも「なんくるないさ～」な天然娘", "カオリ", 0, "高森奈津美", 10, 53, 17, "A", "ハイターイ！　歌って踊って、\n最高に盛り上がるさ～！\nやさやさ、キミも一緒に踊るさ～！");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (162, "魔族", "ルーセント学院", 14, 8, "恋愛小説、恋愛舞台、恋愛漫画の鑑賞", 101801, "多くの男性を魅了する無垢な女教師", "イオ", 0, "伊藤静", 14, 52, 23, "B", "いつも助けてくれてありがとう\n私のほうが年上なのに\n頼ってばかりでごめんなさい～");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (117, "獣人族", "リトルリリカル", 3, 4, "かわいいもの集め", 102001, "お歌もにんじんも、ウサギさんも大好き♪", "ミミ", 0, "日高里菜", 5, 21, 10, "O", "ぴょんぴょん、うさぎさんになりたいな～♪　\nミミ、うさぎさんになれたら、\n最初におにいちゃんに見せてあげるね！");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (150, "ヒューマン", "サレンディア救護院", 9, 6, "観劇、おままごと", 102101, "泣き虫で臆病な守ってあげたい女の子", "クルミ", 0, "植田佳奈", 9, 40, 12, "B", "あの、えっと…私、く、クルミですぅ…\nふ、ふぇぇぇ…ど、どうしようぅ…\nは、恥かしくて…ご、ごめんなさいぃぃ！");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (150, "魔族", "悪魔偽王国軍（ディアボロス）", 22, 11, "ゲーム全般", 102201, "人見知りであまのじゃくな女の子", "ヨリ", 0, "原紗友里", 7, 40, 13, "O", "え、えっと…こ、こういうときって、\nどういうことを言えばいいんだっけ…\nうう、どうしてちゃんと喋れないの…");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (148, "ヒューマン", "サレンディア救護院", 10, 5, "屋内でできる遊び", 102301, "ぷうきちといつも一緒！", "アヤネ", 0, "芹澤優", 9, 38, 14, "B", "この子はね、ぷうきちって言うんだ\n武器なんだけど、しゃべるんだよ♪\n大事な大事な、私の友達なんだぁ～！");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (154, "ヒューマン", "サレンディア救護院", 12, 12, "ご奉仕", 102501, "お嬢さまのためにがんばるドジっ娘メイド", "スズメ", 0, "悠木碧", 9, 43, 15, "O", "うぅ…ごめんなさい～…\nまたキッチンを爆発させてしまいました～\nこれじゃあメイド失格です…");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (144, "獣人族", "牧場（エリザベスパーク）", 1, 1, "あんパン", 102601, "遊びと睡眠が何より大事なぐうたら娘", "リン", 0, "小岩井ことり", 11, 42, 17, "B", "test");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (154, "魔族", "トワイライトキャラバン", 30, 7, "実験、裁縫、料理", 102701, "運命の相手に一途すぎる乙女", "エリコ", 0, "橋本ちなみ", 13, 43, 16, "B", "『壊し屋』の二つ名を持つ私…\nですが、怖がる必要はありませんわ\nあなた様は大切な運命の人ですから…");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (156, "エルフ", "サレンディア救護院", 4, 10, "経営、お茶会", 102801, "救護院を経営する優しい庶民派お嬢様", "サレン", 0, "堀江由衣", 9, 43, 17, "A", "貧乏性？　いいえ、\n「もったいない」の精神で\n日々を過ごしてるだけよ！");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (157, "ヒューマン", "カルミナ", 24, 1, "舞台鑑賞、ダンス", 102901, "歌って踊れる大人気アイドル", "ノゾミ", 0, "日笠陽子", 4, 40, 17, "B", "いつか世界中の人達をファンにしてみせる！\nトップアイドルになるその日まで、\n応援よろしくね♪");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (163, "ヒューマン", "ヴァイスフリューゲル　ランドソル支部", 31, 8, "忍法開発", 103001, "トーゴクの神秘、オシエテクダサイ！", "ニノン", 0, "佐藤聡美", 15, 51, 16, "O", "スシ、ゲイシャ、テンプラ…\nはふぅ～！\nトーゴクの文化はステキデスね～！");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (157, "魔族", "悪魔偽王国軍（ディアボロス）", 22, 12, "占い", 103101, "占いが得意な霊能少女", "シノブ", 0, "大坪由佳", 7, 42, 18, "AB", "私、小さい頃から人には見えないものが\n見えていたんです。今もあなたの後ろに\n一人、二人、三人…賑やかですね");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (157, "ヒューマン", "メルクリウス財団", 12, 3, "慈善事業", 103201, "一人前の商人を目指すパワフルお嬢様", "アキノ", 0, "松嵜麗", 12, 45, 18, "AB", "この私とともにいる限り、\nお金に不自由はさせませんわ！");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (142, "ヒューマン", "牧場（エリザベスパーク）", 3, 3, "漫才", 103301, "みんなを笑顔にするお笑い牧場主", "マヒル", 0, "新田恵海", 11, 35, 20, "B", "オラはどんな時でもみんなに笑顔を届ける\n最高の芸人目指してる！\n一緒に頑張るべ！");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (164, "エルフ", "メルクリウス財団", 16, 3, "ウインドーショッピング", 103401, "純情でほっとけない大人の女性", "ユカリ", 0, "今井麻美", 12, 55, 22, "A", "キミには情けないところばかり\n見られているけど、こんなところ、\nキミ以外には見せないんだからね？");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (118, "エルフ", "リトルリリカル", 2, 2, "お勉強", 103601, "礼儀正しくしっかり者のちびっ子優等生", "キョウカ", 0, "小倉唯", 5, 21, 8, "A", "test");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (149, "ヒューマン", "王宮騎士団（NIGHTMARE）", 11, 8, "剣術、年長者をからかう", 103701, "義理堅くてからかい好きな剣術少女", "トモ", 0, "茅原実里", 8, 43, 13, "A", "test");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (153, "獣人族", "牧場（エリザベスパーク）", 3, 11, "読書、お散歩", 103801, "読書が趣味の病弱少女", "シオリ", 0, "小清水亜美", 11, 40, 14, "A", "ゴホッ、ゴホッ…か、身体は弱いけど、\nせめて気持ちだけでも前向きに…！\nあっ、でもダメ…立ちくらみが…");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (158, "エルフ", "フォレスティエ", 6, 6, "友達作りのイメトレ", 104001, "「友達」に憧れる、エルフの森の女の子", "アオイ", 0, "花澤香菜", 6, 44, 13, "AB", "友達ができるその日まで…\nBB団で\nトレーニングですっ！");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (163, "ヒューマン", "カルミナ", 3, 6, "各種楽器", 104201, "人々を守るために歌う、唱喚士の少女", "チカ", 0, "福原綾香", 4, 46, 17, "O", "私は人々の平和を守るため、唱喚術を使って\n戦います。…最近は、ア、アイドルとしても\n活動してますが、そちらはまだ不慣れで…");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (168, "獣人族", "自警団（カォン）", 9, 8, "お菓子作り", 104301, "男勝りで情に厚いワイルド娘", "マコト", 0, "小松未可子", 10, 54, 17, "O", "腹へってたら言えよな\n簡単でよければ\nすっげー旨いもん食わせてやるよ！");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (172, "魔族", "悪魔偽王国軍（ディアボロス）", 5, 5, "世界征服", 104401, "かつては夜を支配した最強の吸血鬼", "イリヤ", 0, "丹下桜", 7, 50, "??", "A", "test");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (157, "ヒューマン", "ヴァイスフリューゲル　ランドソル支部", 19, 11, "小説を読むこと", 104501, "妄想大好き！　ほんとは照れ屋な女の子", "クウカ", 0, "長妻樹里", 15, 49, 18, "AB", "あなたのことを考えていました\n…逆らえないクウカをああして、こうして\nぐふ、ぐふふふ…");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (158, "獣人族", "メルクリウス財団", 1, 3, "猫とたわむれること", 104601, "弱きを助け強きをくじく猫娘", "タマキ", 0, "沼倉愛美", 12, 48, 19, "AB", "お金もうけの話なら、ぜひともあたしに\n持ってくるにゃ！　稼げるなら１ルピだって\n見逃さないのが、あたしの信条にゃ～♪");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (171, "ヒューマン", "王宮騎士団（NIGHTMARE）", 25, 10, "格闘技、湯浴み", 104701, "素顔を見せない冷静沈着な女性騎士", "ジュン", 0, "川澄綾子", 8, 50, 25, "A", "？？？");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (163, "ヒューマン", "メルクリウス財団", 11, 11, "傭兵などのアルバイト", 104801, "仕事も私事も効率優先な傭兵少女", "ミフユ", 0, "田所あずさ", 12, 49, 20, "O", "私がキミの師匠になってあげる！\nもちろんタダとはいかないわ\n時給はしっかりもらうから");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (168, "ヒューマン", "ラビリンス", 24, 10, "家事全般", 104901, "お姉ちゃんがお世話してあげるからねっ！", "シズル", 0, "生天目仁美", 3, 54, 18, "O", "身の回りのお世話はお姉ちゃんがやってあげるね！\nお料理も、お洗濯も、お掃除も\nお風呂で背中も流してあげちゃうぞっ！");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (120, "魔族", "ルーセント学院", 3, 1, "ファッション誌鑑賞、コスメ集め", 105001, "ちょっとおませな恋に恋する女の子", "ミサキ", 0, "久野美咲", 14, 22, 11, "A", "アタシのこと呼んだ？\nレディの魅力で夢中にさせてあげるわね！");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (166, "ヒューマン", "トワイライトキャラバン", 7, 3, "研究、実験", 105101, "実験が趣味の危険な科学者", "ミツキ", 0, "三石琴乃", 13, 53, 27, "A", "私は科学者だけど、\n医者の真似事もしてるの\n病気になったら診てあげるわ");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (150, "獣人族", "牧場（エリザベスパーク）", 14, 3, "毛繕い、お喋り", 105201, "乙女チックなもふもふアニマル", "リマ", 0, "徳井青空", 11, 100, 17, "A", "私、ごく普通の、どこにでもいる女の子よ！\nみ、見た目以外はね…");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (140, "ヒューマン", "ヴァイスフリューゲル　ランドソル支部", 28, 7, "お菓子屋通い", 105301, "見た目も中身もお子ちゃまな異国の軍人", "モニカ", 0, "辻あゆみ", 15, 33, 17, "A", "「白き翼」こと、ヴァイスフリューゲル…\nその名に恥じぬよう、天高く舞い、\n華麗に敵を倒してみせる！");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (153, "ヒューマン", "カルミナ", 7, 9, "裁縫", 105401, "ファッション大好きなキュートガール", "ツムギ", 0, "木戸衣吹", 4, 45, 14, "AB", "test");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (155, "エルフ", "ヴァイスフリューゲル　ランドソル支部", 7, 4, "観察", 105501, "どこまでも一途に慕う、純情乙女", "アユミ", 0, "大関英里", 15, 43, 16, "O", "test");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (167, "ヒューマン", "トワイライトキャラバン", 11, 7, "釣り", 105601, "人情味溢れる粋でいなせな「姉御」", "ルカ", 0, "佐藤利奈", 13, 54, 25, "B", "test");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (156, "ヒューマン", "？？？", 10, 3, "冒険、おしゃべり", 105701, "空への冒険を夢見る騎空士の少女", "ジータ", 0, "金元寿子", "", 45, 17, "O", "私ね、一人前の騎空士になりたいんだ\nいつか父さんみたいな騎空士になって、\n空の果てまで旅する。それが私の夢だよ！");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (156, "ヒューマン", "美食殿", 31, 3, "食べ歩き、料理", 105801, "いつも元気な腹ペコ少女", "ペコリーヌ", 0, "M・A・O", 1, 46, 17, "O", "あ、あの…何か食べ物持っていませんか？\nもう、お腹ペコペコで…");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (140, "エルフ", "美食殿", 11, 5, "瞑想、動植物の飼育", 105901, "主を慕う、小さなガイド役", "コッコロ", 0, "伊藤美来", 1, 35, 11, "B", "主さまのガイド役を仰せつかりました\nわたくし、主さまに満足していただけるよう\n誠心誠意尽くさせていただきます");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (152, "獣人族", "美食殿", 2, 9, "猫と遊ぶ", 106001, "行き倒れの謎のネコミミ魔法使い", "キャル", 0, "立花理香", 1, 39, 14, "A", "なに、モタモタしてんのよ\n仕方ないから、あたしが手伝ってあげるわ\nいい？　感謝しなさいよね！");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (148, "ヒューマン", "？？？", 11, 8, "冒険、思い出話", 106101, "さまよえる謎の少女", "ムイミ", 0, "潘めぐみ", "", 40, 16, "O", "いいんだ、アタシは……独りでも。大丈夫だから、もう慣れたからさぁ");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (155, "エルフ", "？？？", 17, 6, "キレイな葉っぱを集めること", 106301, "森番を目指すエルフの少女", "アリサ", 0, "優木かな", "", 42, 15, "O", "");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (147, "ドラゴン族", "美食殿", 14, 12, "読書、ストレッチ", 106401, "記憶喪失のドラゴン娘", "シェフィ", 0, "近藤玲奈", 1, "???", 14, "B", "");
