INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (145, "ドラゴン族", "ドラゴンズネスト", 29, 9, "ゲーム", 106601, "口が達者なヘタレドラゴン", "イノリ", 0, "藤田茜", 17, "???", 13, "AB", "");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (168, "ドラゴン族", "ドラゴンズネスト", 17, 4, "絵画、読書", 106701, "妖しい微笑で全てを見透かす臥竜の頭領", "ホマレ", 0, "大西沙織", 17, "???", 25, "O", "");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (160, "ヒューマン", "ラビリンス", 25, 7, "人間観察", 106801, "秘密結社ラビリンスの『迷宮女王』", "ラビリスタ", 0, "沢城みゆき", 3, "??", 25, "AB", "");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (166, "獣人族", "？？？", 1, 7, "占い、支配", 106901, "謎に包まれたランドソルの主", "カイザーインサイト", 0, "蒼井翔太", "", "??", 29, "AB", "");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (149, "エルフ", "？？？", 24, 3, "物真似、芸術鑑賞", 107001, "研究所に隠れ住む物静かなお姉さん", "ネネカ", 0, "井口裕香", "", "??", 24, "O", "");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (165, "ヒューマン", "王宮騎士団（NIGHTMARE）", 7, 2, "強敵との闘争", 107101, "傍若無人な王宮騎士団副団長", "クリスティーナ", 0, "たかはし智秋", 8, "??", 27, "O", "");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (156, "ヒューマン", "美食殿", 31, 3, "食べ歩き、料理", 107501, "いつも元気な腹ペコ少女", "ペコリーヌ（サマー）", 0, "M・A・O", 1, 46, 17, "O", "あ、あの…何か食べ物持っていませんか？\nもう、お腹ペコペコで…");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (140, "エルフ", "美食殿", 11, 5, "瞑想、動植物の飼育", 107601, "主を慕う、小さなガイド役", "コッコロ（サマー）", 0, "伊藤美来", 1, 35, 11, "B", "主さまのガイド役を仰せつかりました\nわたくし、主さまに満足していただけるよう\n誠心誠意尽くさせていただきます");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (154, "ヒューマン", "サレンディア救護院", 12, 12, "ご奉仕", 107701, "お嬢さまのためにがんばるドジっ娘メイド", "スズメ（サマー）", 0, "悠木碧", 9, 43, 15, "O", "うぅ…ごめんなさい～…\nまたキッチンを爆発させてしまいました～\nこれじゃあメイド失格です…");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (152, "獣人族", "美食殿", 2, 9, "猫と遊ぶ", 107801, "行き倒れの謎のネコミミ魔法使い", "キャル（サマー）", 0, "立花理香", 1, 39, 14, "A", "なに、モタモタしてんのよ\n仕方ないから、あたしが手伝ってあげるわ\nいい？　感謝しなさいよね！");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (158, "獣人族", "メルクリウス財団", 1, 3, "猫とたわむれること", 107901, "弱きを助け強きをくじく猫娘", "タマキ（サマー）", 0, "沼倉愛美", 12, 48, 19, "AB", "お金もうけの話なら、ぜひともあたしに\n持ってくるにゃ！　稼げるなら１ルピだって\n見逃さないのが、あたしの信条にゃ～♪");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (163, "ヒューマン", "メルクリウス財団", 11, 11, "傭兵などのアルバイト", 108001, "仕事も私事も効率優先な傭兵少女", "ミフユ（サマー）", 0, "田所あずさ", 12, 49, 20, "O", "私がキミの師匠になってあげる！\nもちろんタダとはいかないわ\n時給はしっかりもらうから");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (157, "魔族", "悪魔偽王国軍（ディアボロス）", 22, 12, "占い", 108101, "占いが得意な霊能少女", "シノブ（ハロウィン）", 0, "大坪由佳", 7, 42, 18, "AB", "私、小さい頃から人には見えないものが\n見えていたんです。今もあなたの後ろに\n一人、二人、三人…賑やかですね");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (130, "魔族", "悪魔偽王国軍（ディアボロス）", 23, 1, "プリンを食べること", 108201, "プリン大好きゴースト娘", "ミヤコ（ハロウィン）", 0, "雨宮天", 7, 32, 14, "B", "難しいことはわからないの～\nただ毎日プリンを食べられるなら、\n幽霊のままでいいの～");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (120, "魔族", "ルーセント学院", 3, 1, "ファッション誌鑑賞、コスメ集め", 108301, "ちょっとおませな恋に恋する女の子", "ミサキ（ハロウィン）", 0, "久野美咲", 14, 22, 11, "A", "アタシのこと呼んだ？\nレディの魅力で夢中にさせてあげるわね！");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (163, "ヒューマン", "カルミナ", 3, 6, "各種楽器", 108401, "人々を守るために歌う、唱喚士の少女", "チカ（クリスマス）", 0, "福原綾香", 4, 46, 17, "O", "私は人々の平和を守るため、唱喚術を使って\n戦います。…最近は、ア、アイドルとしても\n活動してますが、そちらはまだ不慣れで…");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (150, "ヒューマン", "サレンディア救護院", 9, 6, "観劇、おままごと", 108501, "泣き虫で臆病な守ってあげたい女の子", "クルミ（クリスマス）", 0, "植田佳奈", 9, 40, 12, "B", "あの、えっと…私、く、クルミですぅ…\nふ、ふぇぇぇ…ど、どうしようぅ…\nは、恥かしくて…ご、ごめんなさいぃぃ！");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (148, "ヒューマン", "サレンディア救護院", 10, 5, "屋内でできる遊び", 108601, "ぷうきちといつも一緒！", "アヤネ（クリスマス）", 0, "芹澤優", 9, 38, 14, "B", "この子はね、ぷうきちって言うんだ\n武器なんだけど、しゃべるんだよ♪\n大事な大事な、私の友達なんだぁ～！");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (155, "獣人族", "トゥインクルウィッシュ", 27, 8, "人助け、応援", 108701, "人助けが大好き！　前向き格闘娘", "ヒヨリ（ニューイヤー）", 0, "東山奈央", 2, 44, 16, "A", "こんにちは！　ヒヨリでっす！\n困っている人がいたら助けにいくよ！\nよかったら一緒に来ない？");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (158, "ヒューマン", "トゥインクルウィッシュ", 5, 4, "料理、人間観察", 108801, "戦闘のサポートが得意な、心優しい少女", "ユイ（ニューイヤー）", 0, "種田梨沙", 2, 47, 17, "O", "あんまり役に立てるかはわからないけど…\nわたしも頑張って、\nみんなをサポートするね！");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (163, "魔族", "トゥインクルウィッシュ", 12, 1, "読書、乗馬、お茶", 108901, "クールで何事にも真っ直ぐな剣士", "レイ（ニューイヤー）", 0, "早見沙織", 2, 46, 18, "B", "キミと会ったのもきっと何かの縁だ\n一緒に塔の頂上を目指す仲間として\n頑張っていこう。よろしく頼む");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (154, "魔族", "トワイライトキャラバン", 30, 7, "実験、裁縫、料理", 109001, "運命の相手に一途すぎる乙女", "エリコ（バレンタイン）", 0, "橋本ちなみ", 13, 43, 16, "B", "『壊し屋』の二つ名を持つ私…\nですが、怖がる必要はありませんわ\nあなた様は大切な運命の人ですから…");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (168, "ヒューマン", "ラビリンス", 24, 10, "家事全般", 109101, "お姉ちゃんがお世話してあげるからねっ！", "シズル（バレンタイン）", 0, "生天目仁美", 3, 54, 18, "O", "身の回りのお世話はお姉ちゃんがやってあげるね！\nお料理も、お洗濯も、お掃除も\nお風呂で背中も流してあげちゃうぞっ！");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (156, "ヒューマン", "？？？", 1, 12, "読書", 109201, "英霊と契約を結んだマナリアの天才王女", "アン", 0, "日笠陽子", "", 55, 17, "AB", "私はアン！一応、マナリア王国の\n第一王女だけど…あまりかしこまらないで、\n気軽に仲良くしてくれたら嬉しいな！");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (144, "ヒューマン", "？？？", 4, 2, "食べること、眠ること", 109301, "マナリア魔法学院の新入生", "ルゥ", 0, "こやまきみこ", "", 45, 16, "O", "ルゥはルゥですぅ！マナリア魔法学院に\n通ってるですぅ。あなたもルゥの\nお友だちになってくれるですか？");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (167, "半人半竜", "？？？", 3, 11, "ピアノ", 109401, "人を超越した力を有す心優しい竜姫", "グレア", 0, "福原綾香", "", 67, 17, "B", "私はグレア。竜と人、両方の血を\n受け継いでいるの…\nえっと…よ、よろしくね");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (157, "ヒューマン", "ヴァイスフリューゲル　ランドソル支部", 19, 11, "小説を読むこと", 109501, "妄想大好き！　ほんとは照れ屋な女の子", "クウカ（オーエド）", 0, "長妻樹里", 15, 49, 18, "AB", "あなたのことを考えていました\n…逆らえないクウカをああして、こうして\nぐふ、ぐふふふ…");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (163, "ヒューマン", "ヴァイスフリューゲル　ランドソル支部", 31, 8, "忍法開発", 109601, "トーゴクの神秘、オシエテクダサイ！", "ニノン（オーエド）", 0, "佐藤聡美", 15, 51, 16, "O", "スシ、ゲイシャ、テンプラ…\nはふぅ～！\nトーゴクの文化はステキデスね～！");
