INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (163, "魔族", "トゥインクルウィッシュ", 12, 1, "読書、乗馬、お茶", 114001, "クールで何事にも真っ直ぐな剣士", "レイ（ハロウィン）", 0, "早見沙織", 2, 46, 18, "B", "キミと会ったのもきっと何かの縁だ\n一緒に塔の頂上を目指す仲間として\n頑張っていこう。よろしく頼む");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (146, "獣人族", "王宮騎士団（NIGHTMARE）", 25, 11, "ヒーローごっこ", 114101, "ヒーローに憧れる騎士見習いの少女", "マツリ（ハロウィン）", 0, "下田麻美", 8, 40, 12, "O", "");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (140, "ヒューマン", "ヴァイスフリューゲル　ランドソル支部", 28, 7, "お菓子屋通い", 114201, "見た目も中身もお子ちゃまな異国の軍人", "モニカ（マジカル）", 0, "辻あゆみ", 15, 33, 17, "A", "「白き翼」こと、ヴァイスフリューゲル…\nその名に恥じぬよう、天高く舞い、\n華麗に敵を倒してみせる！");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (149, "ヒューマン", "王宮騎士団（NIGHTMARE）", 11, 8, "剣術、年長者をからかう", 114301, "義理堅くてからかい好きな剣術少女", "トモ（マジカル）", 0, "茅原実里", 8, 43, 13, "A", "");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (157, "ヒューマン", "メルクリウス財団", 12, 3, "慈善事業", 114401, "一人前の商人を目指すパワフルお嬢様", "アキノ（クリスマス）", 0, "松嵜麗", 12, 45, 18, "AB", "この私とともにいる限り、\nお金に不自由はさせませんわ！");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (156, "エルフ", "サレンディア救護院", 4, 10, "経営、お茶会", 114501, "救護院を経営する優しい庶民派お嬢様", "サレン（クリスマス）", 0, "堀江由衣", 9, 43, 17, "A", "貧乏性？　いいえ、\n「もったいない」の精神で\n日々を過ごしてるだけよ！");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (164, "エルフ", "メルクリウス財団", 16, 3, "ウインドーショッピング", 114601, "純情でほっとけない大人の女性", "ユカリ（クリスマス）", 0, "今井麻美", 12, 55, 22, "A", "キミには情けないところばかり\n見られているけど、こんなところ、\nキミ以外には見せないんだからね？");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (148, "ヒューマン", "？？？", 11, 8, "冒険、思い出話", 114701, "さまよえる謎の少女", "ムイミ（ニューイヤー）", 0, "潘めぐみ", "", 40, 16, "O", "いいんだ、アタシは……独りでも。大丈夫だから、もう慣れたからさぁ");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (149, "エルフ", "？？？", 24, 3, "物真似、芸術鑑賞", 115001, "研究所に隠れ住む物静かなお姉さん", "ネネカ（ニューイヤー）", 0, "井口裕香", "", "??", 24, "O", "");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (140, "エルフ", "美食殿", 11, 5, "瞑想、動植物の飼育", 115501, "主を慕う、小さなガイド役", "コッコロ（儀装束）", 0, "伊藤美来", 1, 35, 11, "B", "主さまのガイド役を仰せつかりました\nわたくし、主さまに満足していただけるよう\n誠心誠意尽くさせていただきます");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (158, "ヒューマン", "トゥインクルウィッシュ", 5, 4, "料理、人間観察", 115601, "戦闘のサポートが得意な、心優しい少女", "ユイ（儀装束）", 0, "種田梨沙", 2, 47, 17, "O", "あんまり役に立てるかはわからないけど…\nわたしも頑張って、\nみんなをサポートするね！");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (152, "獣人族", "自警団（カォン）", 3, 11, "読書、推理", 115701, "頭脳明晰な美少女名探偵", "カスミ（サマー）", 0, "水瀬いのり", 10, 41, 15, "AB", "");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (150, "獣人族", "牧場（エリザベスパーク）", 14, 3, "毛繕い、お喋り", 115801, "乙女チックなもふもふアニマル", "リマ（シンデレラ）", 0, "徳井青空", 11, 100, 17, "A", "私、ごく普通の、どこにでもいる女の子よ！\nみ、見た目以外はね…");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (168, "獣人族", "自警団（カォン）", 9, 8, "お菓子作り", 115901, "男勝りで情に厚いワイルド娘", "マコト（シンデレラ）", 0, "小松未可子", 10, 54, 17, "O", "腹へってたら言えよな\n簡単でよければ\nすっげー旨いもん食わせてやるよ！");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (155, "獣人族", "自警団（カォン）", 22, 9, "空想、ぬいぐるみ集め", 116001, "マホマホ王国のプリンセス", "マホ（シンデレラ）", 0, "内田真礼", 10, 42, 16, "O", "マホマホ王国のお姫はんの、マホ姫どす！\nけったいな顔してどないしはったん？\nマホマホ王国はずーっと遠くの国なんどす？");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (154, "エルフ", "聖テレサ女学院（なかよし部）", 7, 8, "ダーツ", 116201, "ダウンタウン育ちのダウナー系エルフ", "クロエ（聖学祭）", 0, "種﨑敦美", 16, 42, 17, "O", "");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (156, "ヒューマン", "聖テレサ女学院（なかよし部）", 15, 9, "ダンス、カラオケ", 116301, "自由奔放ナチュラル無礼な現代っ子", "チエル（聖学祭）", 0, "佐倉綾音", 16, 46, 16, "O", "");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (142, "ヒューマン", "聖テレサ女学院（なかよし部）", 28, 2, "読書", 116401, "書庫に眠れる小さな賢人", "ユニ（聖学祭）", 0, "小原好美", 16, 36, 18, "O", "");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (145, "ドラゴン族", "ドラゴンズネスト", 29, 9, "ゲーム", 116501, "口が達者なヘタレドラゴン", "イノリ（タイムトラベル）", 0, "藤田茜", 17, "???", 13, "AB", "");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (156, "ドラゴン族", "ドラゴンズネスト", 25, 6, "格闘技", 116601, "拳で語る喧嘩屋ドラゴン少女", "カヤ（タイムトラベル）", 0, "小市眞琴", 17, "???", 16, "B", "");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (158, "エルフ", "フォレスティエ", 6, 6, "友達作りのイメトレ", 116701, "「友達」に憧れる、エルフの森の女の子", "アオイ（作業服）", 0, "花澤香菜", 6, 44, 13, "AB", "");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (158, "獣人族", "メルクリウス財団", 1, 3, "猫とたわむれること", 116801, "弱きを助け強きをくじく猫娘", "タマキ（作業服）", 0, "沼倉愛美", 12, 48, 19, "AB", "お金もうけの話なら、ぜひともあたしに\n持ってくるにゃ！　稼げるなら１ルピだって\n見逃さないのが、あたしの信条にゃ～♪");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (163, "ヒューマン", "メルクリウス財団", 11, 11, "傭兵などのアルバイト", 116901, "仕事も私事も効率優先な傭兵少女", "ミフユ（作業服）", 0, "田所あずさ", 12, 49, 20, "O", "私がキミの師匠になってあげる！\nもちろんタダとはいかないわ\n時給はしっかりもらうから");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (154, "魔族", "トワイライトキャラバン", 30, 7, "実験、裁縫、料理", 117001, "運命の相手に一途すぎる乙女", "エリコ（サマー）", 0, "橋本ちなみ", 13, 43, 16, "B", "『壊し屋』の二つ名を持つ私…\nですが、怖がる必要はありませんわ\nあなた様は大切な運命の人ですから…");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (168, "ヒューマン", "ラビリンス", 24, 10, "家事全般", 117101, "お姉ちゃんがお世話してあげるからねっ！", "シズル（サマー）", 0, "生天目仁美", 3, 54, 18, "O", "身の回りのお世話はお姉ちゃんがやってあげるね！\nお料理も、お洗濯も、お掃除も\nお風呂で背中も流してあげちゃうぞっ！");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (157, "ヒューマン", "カルミナ", 24, 1, "舞台鑑賞、ダンス", 117201, "歌って踊れる大人気アイドル", "ノゾミ（サマー）", 0, "日笠陽子", 4, 40, 17, "B", "");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (163, "ヒューマン", "カルミナ", 3, 6, "各種楽器", 117301, "人々を守るために歌う、唱喚士の少女", "チカ（サマー）", 0, "福原綾香", 4, 46, 17, "O", "私は人々の平和を守るため、唱喚術を使って\n戦います。…最近は、ア、アイドルとしても\n活動してますが、そちらはまだ不慣れで…");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (153, "ヒューマン", "カルミナ", 7, 9, "裁縫", 117401, "ファッション大好きなキュートガール", "ツムギ（サマー）", 0, "木戸衣吹", 4, 45, 14, "AB", "");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (166, "ヒューマン", "トワイライトキャラバン", 7, 3, "研究、実験", 117501, "実験が趣味の危険な科学者", "ミツキ（オーエド）", 0, "三石琴乃", 13, 53, 27, "A", "私は科学者だけど、\n医者の真似事もしてるの\n病気になったら診てあげるわ");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (150, "エルフ", "ヴァイスフリューゲル　ランドソル支部", 10, 10, "鏡で自分を見ること", 117601, "ボクは誰よりも美しい", "ユキ（オーエド）", 0, "大空直美", 15, 40, 14, "AB", "ボクって本当に美しいなあ…\n可愛くて美しいなんて本当に罪だと思うけど\n生まれもったものだから仕方ないんだ♪");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (158, "獣人族", "自警団（カォン）", 7, 7, "踊り、空手", 117701, "いつでも「なんくるないさ～」な天然娘", "カオリ（ハロウィン）", 0, "高森奈津美", 10, 53, 17, "A", "ハイターイ！　歌って踊って、\n最高に盛り上がるさ～！\nやさやさ、キミも一緒に踊るさ～！");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (163, "ヒューマン", "ヴァイスフリューゲル　ランドソル支部", 31, 8, "忍法開発", 117801, "トーゴクの神秘、オシエテクダサイ！", "ニノン（ハロウィン）", 0, "佐藤聡美", 15, 51, 16, "O", "スシ、ゲイシャ、テンプラ…\nはふぅ～！\nトーゴクの文化はステキデスね～！");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (167, "魔族", "ルーセント学院", 10, 4, "ファッション", 117901, "天真爛漫で人気者のカリスマモデル", "スズナ（ハロウィン）", 0, "上坂すみれ", 14, 48, 17, "O", "ヒデサイ、ちょっす～！　うち、漢字と計算は\nちょっち…てか、おに苦手なんだ～\nでもでも、ファッションだったら任せて～！");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (160, "ヒューマン", "リッチモンド商工会", 19, 9, "お金を数えること、悪だくみ", 118001, "忠義に目覚めた女商人", "クレジッタ", 0, "Lynn", 18, 57, 26, "A", "");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (165, "魔族", "レイジ・レギオン", 28, 12, "歌、読書、詩を書くこと", 118101, "静寂を求め歌う陰気少女", "ランファ", 0, "原田彩楓", 19, 53, 20, "O", "");
