INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (162, "魔族", "ルーセント学院", 14, 8, "恋愛小説、恋愛舞台、恋愛漫画の鑑賞", 119001, "多くの男性を魅了する無垢な女教師", "イオ（ノワール）", 0, "伊藤静", 14, 52, 23, "B", "いつも助けてくれてありがとう\n私のほうが年上なのに\n頼ってばかりでごめんなさい～");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (157, "ヒューマン", "ヴァイスフリューゲル　ランドソル支部", 19, 11, "小説を読むこと", 119101, "妄想大好き！　ほんとは照れ屋な女の子", "クウカ（ノワール）", 0, "長妻樹里", 15, 49, 18, "AB", "あなたのことを考えていました\n…逆らえないクウカをああして、こうして\nぐふ、ぐふふふ…");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (142, "ヒューマン", "牧場（エリザベスパーク）", 3, 3, "漫才", 119201, "みんなを笑顔にするお笑い牧場主", "マヒル（クリスマス）", 0, "新田恵海", 11, 35, 20, "B", "オラはどんな時でもみんなに笑顔を届ける\n最高の芸人目指してる！\n一緒に頑張るべ！");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (156, "ヒューマン", "ラビリンス", 25, 8, "お裁縫", 119301, "人懐っこくてマシンガントークな妹系少女", "リノ（クリスマス）", 0, "阿澄佳奈", 3, 44, 15, "A", "覚えていないと思うんですけど…\n私は妹なんですよ！\nだからお兄ちゃんって呼んでいいですか？");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (130, "魔族", "悪魔偽王国軍（ディアボロス）", 23, 1, "プリンを食べること", 119901, "プリン大好きゴースト娘", "ミヤコ（クリスマス）", 0, "雨宮天", 7, 32, 14, "B", "難しいことはわからないの～\nただ毎日プリンを食べられるなら、\n幽霊のままでいいの～");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (168, "ヒューマン", "ラビリンス", 24, 10, "家事全般", 120001, "お姉ちゃんがお世話してあげるからねっ！", "シズル（ノワール）", 0, "生天目仁美", 3, 54, 18, "O", "身の回りのお世話はお姉ちゃんがやってあげるね！\nお料理も、お洗濯も、お掃除も\nお風呂で背中も流してあげちゃうぞっ！");
