INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (150, "ヒューマン", "サレンディア救護院", 9, 6, "観劇、おままごと", 121301, "泣き虫で臆病な守ってあげたい女の子", "クルミ（ステージ）", 0, "植田佳奈", 9, 40, 12, "B", "あの、えっと…私、く、クルミですぅ…\nふ、ふぇぇぇ…ど、どうしようぅ…\nは、恥かしくて…ご、ごめんなさいぃぃ！");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (120, "魔族", "ルーセント学院", 3, 1, "ファッション誌鑑賞、コスメ集め", 121401, "ちょっとおませな恋に恋する女の子", "ミサキ（ステージ）", 0, "久野美咲", 14, 22, 11, "A", "アタシのこと呼んだ？\nレディの魅力で夢中にさせてあげるわね！");
