INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (159, "魔族", "トワイライトキャラバン", 5, 7, "小説執筆", 121901, "前世を信じる中二病患者、「疾風の冥姫」", "アンナ（パイレーツ）", 0, "髙野麻美", 13, 45, 17, "A", "いいか、絶対に私を真名で呼ぶなよ？\n常に「機関」の眼や耳の存在を疑え\nそれが、生きのびるための術だ…！");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (157, "魔族", "悪魔偽王国軍（ディアボロス）", 22, 12, "占い", 122001, "占いが得意な霊能少女", "シノブ（パイレーツ）", 0, "大坪由佳", 7, 42, 18, "AB", "私、小さい頃から人には見えないものが\n見えていたんです。今もあなたの後ろに\n一人、二人、三人…賑やかですね");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (158, "エルフ", "フォレスティエ", 6, 6, "友達作りのイメトレ", 122101, "「友達」に憧れる、エルフの森の女の子", "アオイ（キャンプ）", 0, "花澤香菜", 6, 44, 13, "AB", "");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (164, "エルフ", "メルクリウス財団", 16, 3, "ウインドーショッピング", 122201, "純情でほっとけない大人の女性", "ユカリ（キャンプ）", 0, "今井麻美", 12, 55, 22, "A", "キミには情けないところばかり\n見られているけど、こんなところ、\nキミ以外には見せないんだからね？");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (149, "魔族", "？？？", 6, 12, "お散歩、お料理", 122301, "けんぞくのご主人様", "ヴァンピィ", 0, "釘宮理恵", "", 41, "??", "AB", "");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (155, "獣人族", "トゥインクルウィッシュ", 27, 8, "人助け、応援", 122401, "人助けが大好き！　前向き格闘娘", "ヒヨリ（サマー）", 0, "東山奈央", 2, 44, 16, "A", "こんにちは！　ヒヨリでっす！\n困っている人がいたら助けにいくよ！\nよかったら一緒に来ない？");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (163, "魔族", "トゥインクルウィッシュ", 12, 1, "読書、乗馬、お茶", 122501, "クールで何事にも真っ直ぐな剣士", "レイ（サマー）", 0, "早見沙織", 2, 46, 18, "B", "キミと会ったのもきっと何かの縁だ\n一緒に塔の頂上を目指す仲間として\n頑張っていこう。よろしく頼む");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (158, "ヒューマン", "トゥインクルウィッシュ", 5, 4, "料理、人間観察", 122601, "戦闘のサポートが得意な、心優しい少女", "ユイ（サマー）", 0, "種田梨沙", 2, 47, 17, "O", "あんまり役に立てるかはわからないけど…\nわたしも頑張って、\nみんなをサポートするね！");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (118, "エルフ", "リトルリリカル", 2, 2, "お勉強", 122701, "礼儀正しくしっかり者のちびっ子優等生", "キョウカ（サマー）", 0, "小倉唯", 5, 21, 8, "A", "");
