INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (150, "魔族", "悪魔偽王国軍（ディアボロス）", 22, 11, "ゲーム全般", 124101, "人見知りであまのじゃくな女の子", "ヨリ（クリスマス）", 0, "原紗友里", 7, 40, 13, "O", "え、えっと…こ、こういうときって、\nどういうことを言えばいいんだっけ…\nうう、どうしてちゃんと喋れないの…");
