INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (166, "ヒューマン", "トワイライトキャラバン", 7, 3, "研究、実験", 124701, "実験が趣味の危険な科学者", "ミツキ（ニューイヤー）", 0, "三石琴乃", 13, 53, 27, "A", "私は科学者だけど、\n医者の真似事もしてるの\n病気になったら診てあげるわ");
