INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (148, "ヒューマン", "？？？", 11, 8, "冒険、思い出話", 125001, "さまよえる謎の少女", "ムイミ（リベレイター）", 0, "潘めぐみ", "", 40, 16, "O", "いいんだ、アタシは……独りでも。大丈夫だから、もう慣れたからさぁ");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (158, "獣人族", "メルクリウス財団", 1, 3, "猫とたわむれること", 125101, "弱きを助け強きをくじく猫娘", "タマキ（カフェ）", 0, "沼倉愛美", 12, 48, 19, "AB", "お金もうけの話なら、ぜひともあたしに\n持ってくるにゃ！　稼げるなら１ルピだって\n見逃さないのが、あたしの信条にゃ～♪");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (140, "ヒューマン", "ヴァイスフリューゲル　ランドソル支部", 28, 7, "お菓子屋通い", 125201, "見た目も中身もお子ちゃまな異国の軍人", "モニカ（カフェ）", 0, "辻あゆみ", 15, 33, 17, "A", "「白き翼」こと、ヴァイスフリューゲル…\nその名に恥じぬよう、天高く舞い、\n華麗に敵を倒してみせる！");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (140, "エルフ", "美食殿", 11, 5, "瞑想、動植物の飼育", 125301, "主を慕う、小さなガイド役", "コッコロ（レンジャー）", 0, "伊藤美来", 1, 35, 11, "B", "主さまのガイド役を仰せつかりました\nわたくし、主さまに満足していただけるよう\n誠心誠意尽くさせていただきます");
INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (153, "獣人族", "牧場（エリザベスパーク）", 3, 11, "読書、お散歩", 125401, "読書が趣味の病弱少女", "シオリ（レンジャー）", 0, "小清水亜美", 11, 40, 14, "A", "ゴホッ、ゴホッ…か、身体は弱いけど、\nせめて気持ちだけでも前向きに…！\nあっ、でもダメ…立ちくらみが…");
