INSERT INTO `v1_5b1381cea6690da0c148e5e9e5f7ca6219f37598dc5d471c2e0ee373cdd3efa6` VALUES (152, "獣人族", "美食殿", 2, 9, "猫と遊ぶ", 127201, "行き倒れの謎のネコミミ魔法使い", "キャル（編入生）", 0, "立花理香", 1, 39, 14, "A", "なに、モタモタしてんのよ\n仕方ないから、あたしが手伝ってあげるわ\nいい？　感謝しなさいよね！");
